import{_ as e,o as t,c as o,a5 as c}from"./chunks/framework.Dep_XxFZ.js";const u=JSON.parse('{"title":"包与依赖关系","description":"","frontmatter":{},"headers":[],"relativePath":"npm-package-dependency.md","filePath":"npm-package-dependency.md","lastUpdated":1787446135000}'),a={name:"npm-package-dependency.md"};function n(s,d,i,r,l,p){return t(),o("div",null,[...d[0]||(d[0]=[c(`<h1 id="包与依赖关系" tabindex="-1">包与依赖关系 <a class="header-anchor" href="#包与依赖关系" aria-label="Permalink to &quot;包与依赖关系&quot;">​</a></h1><p>XiHan.UI 是一个 pnpm workspace。<code>packages/*/*</code> 是对外发布的库包（按角色分 <code>adapters</code> / <code>design</code> / <code>features</code> / <code>engine</code> 四组），<code>tooling/*</code> 是内部工具（永不发布）。</p><h2 id="全部库包" tabindex="-1">全部库包 <a class="header-anchor" href="#全部库包" aria-label="Permalink to &quot;全部库包&quot;">​</a></h2><table tabindex="0"><thead><tr><th>包</th><th>版本</th><th>依赖</th><th>peer 依赖</th><th>层</th></tr></thead><tbody><tr><td><code>@xihan-ui/kernel</code></td><td><code>1.0.0-alpha.3</code></td><td><code>motion</code></td><td>—</td><td>1</td></tr><tr><td><code>@xihan-ui/machine</code></td><td><code>1.0.0-alpha.3</code></td><td><code>kernel</code></td><td>—</td><td>1</td></tr><tr><td><code>@xihan-ui/tokens</code></td><td><code>1.0.0-alpha.3</code></td><td>—</td><td>—</td><td>1</td></tr><tr><td><code>@xihan-ui/icons</code></td><td><code>1.0.0-alpha.3</code></td><td>—</td><td>—</td><td>1</td></tr><tr><td><code>@xihan-ui/motion</code></td><td><code>1.0.0-alpha.3</code></td><td>—</td><td>—</td><td>1</td></tr><tr><td><code>@xihan-ui/behavior</code></td><td><code>1.0.0-alpha.3</code></td><td><code>kernel</code> <code>motion</code></td><td>—</td><td>2</td></tr><tr><td><code>@xihan-ui/position</code></td><td><code>1.0.0-alpha.3</code></td><td><code>kernel</code></td><td>—</td><td>2</td></tr><tr><td><code>@xihan-ui/code-highlight</code></td><td><code>1.0.0-alpha.3</code></td><td><code>kernel</code></td><td>—</td><td>2</td></tr><tr><td><code>@xihan-ui/chat-stream</code></td><td><code>1.0.0-alpha.3</code></td><td><code>kernel</code></td><td>—</td><td>2</td></tr><tr><td><code>@xihan-ui/markdown</code></td><td><code>1.0.0-alpha.3</code></td><td>—</td><td>—</td><td>2</td></tr><tr><td><code>@xihan-ui/sound</code></td><td><code>1.0.0-alpha.3</code></td><td><code>kernel</code></td><td>—</td><td>2</td></tr><tr><td><code>@xihan-ui/animations</code></td><td><code>1.0.0-alpha.3</code></td><td><code>kernel</code> <code>motion</code></td><td>—</td><td>2</td></tr><tr><td><code>@xihan-ui/headless</code></td><td><code>1.0.0-alpha.3</code></td><td><code>kernel</code> <code>machine</code> <code>behavior</code> <code>motion</code> + <code>@internationalized/date</code></td><td>—</td><td>3</td></tr><tr><td><code>@xihan-ui/styles</code></td><td><code>1.0.0-alpha.3</code></td><td><code>tokens</code>（只取其 CSS 产物）</td><td>—</td><td>3</td></tr><tr><td><code>@xihan-ui/backgrounds</code></td><td><code>1.0.0-alpha.3</code></td><td><code>kernel</code> <code>behavior</code> <code>motion</code></td><td>—</td><td>3</td></tr><tr><td><code>@xihan-ui/vue</code></td><td><code>1.0.0-alpha.3</code></td><td><code>kernel</code> <code>machine</code> <code>behavior</code> <code>motion</code> <code>headless</code> <code>position</code> <code>code-highlight</code></td><td><code>vue</code>、<code>backgrounds</code>（可选）、<code>sound</code>（可选）</td><td>4</td></tr><tr><td><code>@xihan-ui/web-components</code></td><td><code>1.0.0-alpha.3</code></td><td><code>kernel</code> <code>machine</code> <code>behavior</code> <code>motion</code> <code>headless</code> <code>position</code> <code>code-highlight</code></td><td><code>backgrounds</code>（可选）</td><td>4</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">版本状态</p><p>17 个包都已发布到 npm，版本 <code>1.0.0-alpha.3</code>，<code>latest</code> 与 <code>alpha</code> 两个 dist-tag 都指向它。这是 <strong>alpha 预发布</strong>：不承诺语义化版本，接口还会变，不要用于生产。</p><p>发布走 changesets，所有库包同属一个 fixed 版本组，一起升到同一个版本号。</p></div><h2 id="依赖图" tabindex="-1">依赖图 <a class="header-anchor" href="#依赖图" aria-label="Permalink to &quot;依赖图&quot;">​</a></h2><p>箭头方向 = 依赖方向，只画实际声明的依赖。同层之间只有 <code>machine → kernel</code> 与 <code>kernel → motion</code> 两条横向依赖。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>层 4   ┌─────────────┐       ┌──────────────────┐</span></span>
<span class="line"><span>       │     vue     │       │  web-components  │  peer: backgrounds（可选）；vue 另有 peer: sound（可选）、vue</span></span>
<span class="line"><span>       └──────┬──────┘       └────────┬─────────┘</span></span>
<span class="line"><span>              │  kernel · machine · motion · behavior · headless · position · code-highlight</span></span>
<span class="line"><span>              └───────────┬───────────┘</span></span>
<span class="line"><span>                          ▼</span></span>
<span class="line"><span>层 3   ┌──────────────┐  ┌───────────────────┐   ┌────────────────┐</span></span>
<span class="line"><span>       │   headless   │  │    backgrounds    │   │ styles（纯CSS）│</span></span>
<span class="line"><span>       └──────┬───────┘  └─────────┬─────────┘   └───────┬────────┘</span></span>
<span class="line"><span>  kernel·machine·behavior·motion  kernel·behavior·motion   tokens 的 CSS 产物</span></span>
<span class="line"><span>        + @internationalized/date</span></span>
<span class="line"><span>              │                    │</span></span>
<span class="line"><span>              ▼                    ▼</span></span>
<span class="line"><span>层 2   ┌──────────┐ ┌──────────┐ ┌────────────────┐ ┌─────────────┐ ┌───────┐ ┌────────────┐ ┌──────────┐</span></span>
<span class="line"><span>       │ behavior │ │ position │ │ code-highlight │ │ chat-stream │ │ sound │ │ animations │ │ markdown │</span></span>
<span class="line"><span>       └────┬─────┘ └────┬─────┘ └───────┬────────┘ └──────┬──────┘ └───┬───┘ └─────┬──────┘ └──────────┘</span></span>
<span class="line"><span>            └────────────┴───────────────┴─────────────────┴───────────┴───────────┘            无依赖</span></span>
<span class="line"><span>                          ▼</span></span>
<span class="line"><span>层 1   ┌──────────┐  ┌──────────┐  ┌──────────┐   ┌──────────┐  ┌───────┐</span></span>
<span class="line"><span>       │  kernel  │◄─┤ machine  │  │  motion  │   │  tokens  │  │ icons │</span></span>
<span class="line"><span>       └────┬─────┘  └──────────┘  └──────────┘   └──────────┘  └───────┘</span></span>
<span class="line"><span>            └──────────────────────────▲            无依赖        无依赖</span></span>
<span class="line"><span>                                  零运行时依赖</span></span></code></pre></div><p>三个包完全独立、可以单独用：</p><ul><li><strong><code>@xihan-ui/tokens</code></strong>——只要设计令牌与主题运行时，不要组件；</li><li><strong><code>@xihan-ui/markdown</code></strong>——只要流式 Markdown 渲染内核；</li><li><strong><code>@xihan-ui/styles</code></strong>——纯 CSS，它对 <code>tokens</code> 的依赖只是为了 <code>@import</code> 令牌产物，不引入任何 JS。</li></ul><h2 id="依赖规则" tabindex="-1">依赖规则 <a class="header-anchor" href="#依赖规则" aria-label="Permalink to &quot;依赖规则&quot;">​</a></h2><p>分层拓扑写在 <code>tooling/eslint-config/src/layers.json</code> 里，由 dependency-cruiser 在 <code>pnpm boundaries</code> 时强制。层级越低越基础，只能依赖 <code>canDependOn</code> 列出的包。</p><p>除分层外还有四条规则：</p><table tabindex="0"><thead><tr><th>规则</th><th>内容</th></tr></thead><tbody><tr><td><code>no-circular</code></td><td>禁止循环依赖</td></tr><tr><td><code>no-unresolvable</code></td><td>解析不出来的 import——最常见的成因正是「伸手够了邻层却没在 <code>package.json</code> 里声明依赖」</td></tr><tr><td><code>styles-no-js-deps</code></td><td><code>styles</code> 是纯 CSS，不得依赖任何 JS 包</td></tr><tr><td><code>no-external-in-packages</code></td><td>库包的运行时代码不得引第三方</td></tr></tbody></table><h2 id="第三方运行时依赖" tabindex="-1">第三方运行时依赖 <a class="header-anchor" href="#第三方运行时依赖" aria-label="Permalink to &quot;第三方运行时依赖&quot;">​</a></h2><p><strong>全库只有一个</strong>：<code>@internationalized/date</code>，只在 <code>@xihan-ui/headless</code> 的日期族里用（零框架的纯数据包，无副作用）。</p><p>以下东西都是自研的，不引第三方：</p><table tabindex="0"><thead><tr><th>能力</th><th>包</th><th>常见的第三方选择</th></tr></thead><tbody><tr><td>浮层定位</td><td><code>position</code></td><td>Floating UI</td></tr><tr><td>代码着色</td><td><code>code-highlight</code></td><td>Shiki / Prism</td></tr><tr><td>Web Components 响应式基类</td><td><code>web-components</code></td><td>Lit</td></tr><tr><td>Markdown 渲染</td><td><code>markdown</code></td><td>markdown-it / marked</td></tr><tr><td>状态机</td><td><code>machine</code></td><td>XState</td></tr></tbody></table><p>要新增第三方运行时依赖，必须逐条登记进白名单并写明理由与摘除条件，<code>check-runtime-deps</code> 门禁盯着这件事。</p><div class="tip custom-block"><p class="custom-block-title">开发期第三方是另一回事</p><p><code>@lit/reactive-element</code> 与 <code>commonmark-spec</code> 出现在 workspace catalog 里，但它们只供测试对拍——前者用于差分校验自研响应式基类，后者用于读 CommonMark 官方用例。两者都不进任何包的运行时依赖。</p></div><h2 id="版本约定" tabindex="-1">版本约定 <a class="header-anchor" href="#版本约定" aria-label="Permalink to &quot;版本约定&quot;">​</a></h2><ul><li>内部运行时依赖一律 <code>workspace:^</code>（发布时展开为 <code>^1.0.0-alpha.3</code> 区间），内部开发期依赖用 <code>workspace:*</code>；</li><li>第三方版本只从 workspace catalog 取，包内写 <code>catalog:</code>，<strong>不得内联版本号</strong>（<code>check-exact-pins</code> 门禁）；</li><li>升级只改 <code>pnpm-workspace.yaml</code> 的 catalog 一处。</li></ul><h2 id="产物契约" tabindex="-1">产物契约 <a class="header-anchor" href="#产物契约" aria-label="Permalink to &quot;产物契约&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>值</th></tr></thead><tbody><tr><td>模块格式</td><td>ESM only，不提供 CJS</td></tr><tr><td>Node</td><td><code>&gt;= 18</code></td></tr><tr><td>类型</td><td>每个入口一份 <code>.d.ts</code></td></tr><tr><td>副作用</td><td>全部 <code>sideEffects: false</code>，<code>styles</code> 与 <code>tokens/tokens.css</code> 除外</td></tr></tbody></table><p><code>pnpm gate:publish</code> 逐包跑 publint 与 attw，按 ESM-only 的支持面校验 exports 条件与类型解析（<code>node16-from-ESM</code> 与 <code>bundler</code> 两列）。</p><h2 id="子路径导出" tabindex="-1">子路径导出 <a class="header-anchor" href="#子路径导出" aria-label="Permalink to &quot;子路径导出&quot;">​</a></h2><p>主入口之外还开了子路径的包：</p><table tabindex="0"><thead><tr><th>包</th><th>子路径</th></tr></thead><tbody><tr><td><code>@xihan-ui/kernel</code></td><td><code>./anatomy</code> <code>./attrs</code> <code>./compose</code> <code>./constants</code> <code>./deprecations</code> <code>./guards</code> <code>./id-generator</code> <code>./merge-props</code> <code>./metadata</code> <code>./normalize-props</code> <code>./runtime-config</code> <code>./scope</code> <code>./skin-check</code> <code>./types</code></td></tr><tr><td><code>@xihan-ui/machine</code></td><td><code>./create-machine</code> <code>./delay</code> <code>./errors</code> <code>./form-reset</code> <code>./guards</code> <code>./service</code> <code>./setup</code> <code>./state</code> <code>./transitions</code> <code>./vanilla</code></td></tr><tr><td><code>@xihan-ui/behavior</code></td><td><code>./dispatch</code> <code>./presence</code></td></tr><tr><td><code>@xihan-ui/position</code></td><td><code>./compute</code></td></tr><tr><td><code>@xihan-ui/code-highlight</code></td><td><code>./languages</code> <code>./tokenize</code></td></tr><tr><td><code>@xihan-ui/tokens</code></td><td><code>./runtime</code> <code>./tokens.css</code> <code>./tokens.json</code></td></tr><tr><td><code>@xihan-ui/icons</code></td><td><code>./codegen</code></td></tr><tr><td><code>@xihan-ui/vue</code></td><td><code>./backgrounds</code> <code>./sound</code></td></tr><tr><td><code>@xihan-ui/web-components</code></td><td><code>./define</code> <code>./backgrounds</code> <code>./custom-elements.json</code></td></tr><tr><td><code>@xihan-ui/styles</code></td><td>每份皮肤一条 CSS，共 125 条（119 份组件皮肤 + 6 份共享层），另有 <code>./index.css</code> 与 <code>./index.unlayered.css</code> 两个整包入口</td></tr></tbody></table><p>其余七个包（<code>headless</code> / <code>motion</code> / <code>animations</code> / <code>backgrounds</code> / <code>chat-stream</code> / <code>markdown</code> / <code>sound</code>）只有主入口。</p><p>组件<strong>没有</strong>单独的子路径导出——按需引入靠 tree-shaking，不靠手写路径。</p><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="./overview#分层与依赖矩阵">架构总览</a></li><li><a href="./installation">安装与接入</a></li><li><a href="./guide/testing#结构门禁">测试与质量门禁</a></li></ul>`,32)])])}const m=e(a,[["render",n]]);export{u as __pageData,m as default};
